const headers = $input.first().json.headers || {};
const authHeader = headers.authorization || headers.Authorization;
if (!authHeader || typeof authHeader !== 'string') { throw new Error('Unauthorized'); }
const parts = authHeader.split(' ');
if (parts.length < 2 || !parts[1]) { throw new Error('Unauthorized'); }
const tokenParts = parts[1].split('.');
if (tokenParts.length < 2) { throw new Error('Unauthorized'); }
const base64 = tokenParts[1].replace(/-/g, '+').replace(/_/g, '/');
const payload = JSON.parse(Buffer.from(base64, 'base64').toString('utf8'));
const body = $input.first().json.body || {};
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const MAX_CHUNKS = 40;
const bookId = UUID_RE.test(String(body.book_id || '')) ? String(body.book_id) : null;
const chunks = Array.isArray(body.chunks) ? body.chunks : [];
let err = null;
const clean = [];
const seen = new Set();
if (!bookId) err = 'معرّف الكتاب غير صالح';
else if (chunks.length < 1 || chunks.length > MAX_CHUNKS) err = 'عدد المقاطع في الطلب لازم يكون بين 1 و ' + MAX_CHUNKS;
else {
  for (const c of chunks) {
    const idx = Number(c && c.chunk_index);
    const content = c && typeof c.content === 'string' ? c.content.trim() : '';
    if (!Number.isInteger(idx) || idx < 0 || idx > 20000 || !content || seen.has(idx)) { err = 'مقطع غير صالح'; break; }
    seen.add(idx);
    const pg = Number(c.page);
    clean.push({
      chunk_index: idx,
      chapter: c.chapter ? String(c.chapter).slice(0, 200) : '',
      page: Number.isInteger(pg) && pg > 0 && pg < 1000000 ? pg : null,
      content: content.slice(0, 4000)
    });
  }
}
const prog = parseInt(body.progress, 10);
return {
  teacherId: payload.sub,
  bookId,
  chunks: err ? [] : clean,
  progress: Number.isInteger(prog) ? Math.max(0, Math.min(99, prog)) : 0,
  isValid: err === null,
  validationError: err
};

const cfg = $('Validate & Config').first().json;
// عنصر لكل مقطع: بنعمل embedding لكل واحد لوحده (زي النسخة اللي اشتغلت) عشان ترتيب النتائج مضمون
return cfg.chunks.map((c, i) => ({ json: { idx: i, text: c.content } }));

const cfg = $('Validate & Config').first().json;
const items = $input.all().map(i => i.json || {});
const fail = (code, message) => ({ json: { ok: false, code, message } });

if (items.length !== cfg.chunks.length) return fail('AI_ERROR', 'عدد نتائج الـ embedding لا يطابق عدد المقاطع.');

const rows = [];
for (let i = 0; i < items.length; i++) {
  const raw = items[i];
  const v = raw.embedding && Array.isArray(raw.embedding.values) ? raw.embedding.values : null;
  if (!v) {
    const s = JSON.stringify(raw.error || raw).slice(0, 400);
    if (/429|RESOURCE_EXHAUSTED|quota|rate.?limit|overloaded|503|UNAVAILABLE/i.test(s)) {
      return fail('BUSY', 'خدمة الفهرسة مشغولة (حد Gemini)، هنعيد المحاولة تلقائيًا.');
    }
    return fail('AI_ERROR', 'تعذّرت فهرسة المقاطع (خطأ من خدمة الـ embedding).');
  }
  // vector(768) في قاعدة البيانات - لو الحجم مختلف نوقف بدل ما نحفظ بيانات غلط
  if (v.length !== 768) return fail('EMBED_DIM', 'حجم الـ embedding غير متوقع (المطلوب 768). راجع outputDimensionality في n8n.');
  const c = cfg.chunks[i];
  rows.push({ chunk_index: c.chunk_index, chapter: c.chapter, page: c.page, content: c.content, embedding: '[' + v.join(',') + ']' });
}
return { json: { ok: true, rowsJson: JSON.stringify(rows), count: rows.length } };
